SELECT , b.bank_name
FROM bank_loan_product p
LEFT JOIN bank_info b ON p.bank_id = b.id

    AND p.bank_id = #{bankId}
    AND p.product_name LIKE CONCAT('%', #{productName}, '%')
    AND p.product_code = #{productCode}
    AND p.status = #{status}

ORDER BY p.sort_order ASC, p.create_time DESC

mapper.update:
UPDATE bank_loan_product
bank_id = #{bankId}, product_name = #{productName}, product_code = #{productCode}, min_amount = #{minAmount}, max_amount = #{maxAmount}, min_term_months = #{minTermMonths}, max_term_months = #{maxTermMonths}, interest_rate = #{interestRate}, description = #{description}, requirements = #{requirements}, status = #{status}, sort_order = #{sortOrder}, remark = #{remark}, update_by = #{updateBy}, update_time = NOW()
WHERE id = #{id}
